mapper.update:
update ai_credential
   set current_secret_revision = #{revision}, revision = revision + 1, updated_at = now()
 where id = #{credentialId}

update ai_credential_secret
   set state = 'RETIRED'
 where credential_id = #{credentialId} and secret_revision < #{revision}

mapper.select:
select ciphertext, nonce, key_id, state
  from ai_credential_secret
 where credential_id = #{credentialId} and secret_revision = #{revision}

mapper.update:
update ai_credential
   set enabled = #{enabled}, revision = revision + 1, updated_at = now()
 where id = #{id}
